<template><view class="page"><MeetingContentHeader title="会议议程" :activity-id="activityId" /><view class="filters"><picker :range="dates" @change="dateIndex = $event.detail.value"><view>{{ dates[dateIndex] || '全部日期' }}</view></picker><picker :range="venues" range-key="name" @change="venueIndex = $event.detail.value"><view>{{ venues[venueIndex]?.name || '全部会场' }}</view></picker></view><view v-if="loading" class="state">加载中...</view><view v-else class="list"><view v-for="item in filtered" :key="item.scheduleId" class="card"><view class="time">{{ clock(item.startTime) }}{{ item.endTime ? ' - ' + clock(item.endTime) : '' }}</view><view class="title">{{ item.name }}</view><view class="sub">{{ [item.venueName, item.topicName].filter(Boolean).join(' · ') }}</view><view v-if="item.speakers" class="sub">主讲：{{ item.speakers }}</view></view><view v-if="!filtered.length" class="state">暂无匹配日程</view></view></view></template>
<script setup>import { computed, ref } from 'vue'; import { onLoad } from '@dcloudio/uni-app'; import MeetingContentHeader from '@/components/MeetingContentHeader.vue'; import { getPortalSchedule } from '@/api/portal/meeting'; const activityId=ref(''); const rows=ref([]); const loading=ref(true); const dateIndex=ref(0); const venueIndex=ref(0); const dates=computed(()=>['全部日期',...Array.from(new Set(rows.value.map(x=>String(x.date||'').slice(0,10)).filter(Boolean)))]); const venues=computed(()=>[{name:'全部会场',venueId:''},...Array.from(new Map(rows.value.filter(x=>x.venueId).map(x=>[x.venueId,{name:x.venueName,venueId:x.venueId}])).values())]); const filtered=computed(()=>rows.value.filter(x=>(!dateIndex.value||String(x.date||'').slice(0,10)===dates.value[dateIndex.value])&&(!venueIndex.value||x.venueId===venues.value[venueIndex.value]?.venueId))); const clock=v=>String(v||'').slice(11,16); onLoad(o=>{activityId.value=o?.activityId||'';getPortalSchedule(activityId.value).then(r=>rows.value=r.data||[]).finally(()=>loading.value=false)});</script><style scoped>.page{min-height:100vh;background:#f5f7fa}.filters{display:flex;gap:20rpx;padding:105rpx 24rpx 18rpx;background:#fff}.filters picker{flex:1;padding:16rpx;border-radius:12rpx;background:#f5f7fa;color:#606266}.list{padding:20rpx 24rpx}.card{padding:24rpx;margin-bottom:18rpx;background:#fff;border-radius:16rpx}.time{color:#409eff;font-size:24rpx}.title{margin:10rpx 0;font-weight:600}.sub{margin-top:8rpx;color:#909399;font-size:24rpx}.state{padding:160rpx 24rpx;text-align:center;color:#909399}</style>
